PHRASEBOOK_CATEGORIES=[p(*x) for x in [("greetings_a1","Greetings",[("ཀུ་ཟུ་བཏབ་ག་ལེར་ཕེབས།","greeting"),("ཁྱོད་རང་གི་མིང་ག་ཅི་ཨིན།","asking a name"),("ངའི་མིང་བཀྲ་ཤིས་ཨིན།","introducing yourself")]),("thanks_a1","Thanks",[("ཐུགས་རྗེ་ཆེ།","saying thank you"),("ཐུགས་རྗེ་ཆེ་ལེགས།","polite thanks"),("དགའ་བསུ་ཡིན།","responding politely")]),("shopping_a1","Shopping",[("གོང་ཚད་ག་དེ་ཅིག་ཨིན།","asking price"),("ང་འདི་དགོ།","requesting an item"),("འདི་ག་དེ་ཅིག་ཨིན།","asking the cost")]),("directions_a1","Directions",[("སློབ་གྲྭ་ག་ཏེ་ཡོད།","asking location"),("གཡས་ཕྱོགས་ལུ་འགྱོ།","giving directions"),("གཡོན་ཕྱོགས་ལུ་འགྱོ།","giving another direction")]),("help_a1","Help",[("ང་ལུ་རོགས་རམ་གནང་གནང་།","asking for help"),("ང་ལུ་ཧ་མ་གོ།","saying you do not understand"),("ཡང་བསྐྱར་གསུང་གནང་།","asking someone to repeat")])]]
