ASSESSMENT_BANK=[AssessmentQuestion(id=f"dz-a1-{i:03}",skill=s,difficulty="A1",question=q,options=o,correct=c) for i,(s,q,o,c) in enumerate([("vocabulary","You meet someone and want to greet them politely. Which Dzongkha phrase should you use?",["hello","goodbye","water","school"],"hello"),("grammar","You want to say “I am not a teacher.” Which Dzongkha sentence is correct?",["ང་དགེ་རྒན་མེན།","ང་དགེ་རྒན་ཨིན།","ང་སློབ་ཕྲུག་ཨིན།","ཁོ་དགེ་རྒན་ཨིན།"],"ང་དགེ་རྒན་མེན།"),("vocabulary","You are talking about your mother. Which Dzongkha word should you use?",["mother","father","friend","school"],"mother"),("grammar","You need to ask someone where they are. Which Dzongkha question should you use?",["ཁྱོད་རང་ག་ཏེ་ཨིན།","འདི་ག་ཅི་ཨིན།","གོང་ཚད་ག་དེ་ཅིག་ཨིན།","ཀུ་ཟུ་བཏབ་ག་ལེར་ཕེབས།"],"ཁྱོད་རང་ག་ཏེ་ཨིན།"),("vocabulary","You need water. Which Dzongkha word means “water”?",["water","rice","tea","price"],"water"),("reading","དཔེ་ཆ་ཅོག་ཙེའི་སྟེང་ལུ་ཡོད། You read the sentence above. Where is the book?",["On the table","At school","In the shop","At home"],"On the table"),("communication","You need help from someone nearby. Which Dzongkha phrase should you use?",["ང་ལུ་རོགས་རམ་གནང་གནང་།","ཐུགས་རྗེ་ཆེ།","ལེགས་སོ།","ཀུ་ཟུ་བཏབ་ག་ལེར་ཕེབས།"],"ང་ལུ་རོགས་རམ་གནང་གནང་།"),("vocabulary","You are making plans for the next day. Which Dzongkha word means “tomorrow”?",["tomorrow","today","morning","right"],"tomorrow"),("grammar","You want to tell someone that you are at home. Which Dzongkha sentence is correct?",["ང་ཁྱིམ་ནང་ལུ་ཨིན།","ང་སློབ་གྲྭར་འགྱོ།","ང་ལུ་ཧ་མ་གོ།","ཁོ་དགེ་རྒན་ཨིན།"],"ང་ཁྱིམ་ནང་ལུ་ཨིན།"),("communication","You did not understand what someone said. Which Dzongkha phrase should you use?",["ང་ལུ་ཧ་མ་གོ།","ཐུགས་རྗེ་ཆེ།","ཀུ་ཟུ་བཏབ་ག་ལེར་ཕེབས།","ལེགས་སོ།"],"ང་ལུ་ཧ་མ་གོ།")],1)]
